import json
import os
import re
def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):
    if not os.path.exists(file_path):
        raise ValueError(f"File {file_path} does not exist")
    with open(file_path, 'r') as f:
        try:
            data = json.load(f)
        except json.JSONDecodeError:
            raise ValueError(f"File {file_path} is not valid JSON")
    for req in INPUT_JSON['required']:
        if req not in data:
            raise ValueError(f"Required attribute '{req}' is missing")
    for prop, prop_schema in INPUT_JSON['properties'].items():
        if prop in data:
            expected_type = prop_schema['type']
            if not isinstance(data[prop], expected_type):
                raise ValueError(f"Attribute '{prop}' has wrong type, expected {expected_type}")
    if 'email' in data and not re.match(EMAIL_REGEX, data['email']):
        raise ValueError("Email format is invalid")
    if attribute not in data:
        raise ValueError(f"Attribute '{attribute}' not found in JSON")
    return data[attribute]

