import os
def task_func(directory, string):
    def search(data, target):
        if isinstance(data, dict):
            for key, value in data.items():
                if isinstance(key, str) and key == target:
                    return True
                if search(value, target):
                    return True
        elif isinstance(data, list):
            for item in data:
                if search(item, target):
                    return True
        elif isinstance(data, str) and data == target:
            return True
        return False

    result = []
    for root, dirs, files in os.walk(directory):
        for file in files:
            if file.endswith('.json'):
                path = os.path.join(root, file)
                try:
                    with open(path, 'r') as f:
                        data = json.load(f)
                    if search(data, string):
                        result.append(path)
                except (json.JSONDecodeError, IOError):
                    continue
    return result

