import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError:
        raise ValueError("JSON data is malformed")
    if not data:
        raise ValueError("JSON data is empty")
    countries = []
    populations = []
    for entry in data:
        if not isinstance(entry.get("Country"), str):
            raise ValueError("Country names must be strings")
        pop = entry.get("Population")
        if not isinstance(pop, (int, float)):
            raise ValueError("Population must be numeric")
        if pop < 0:
            raise ValueError("Population cannot be negative")
        if isinstance(pop, float):
            pop = int(math.floor(pop))
        countries.append(entry["Country"])
        populations.append(pop)
    df = pd.DataFrame({"Country": countries, "Population": populations})
    file_path = os.path.join(output_dir, file_name)
    try:
        df.to_csv(file_path, index=False)
    except IOError:
        raise IOError("Cannot write file to the specified directory")
    return file_path, df

import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    data = json.loads(json_str)

    def remove_none(obj):
        if isinstance(obj, dict):
            new_dict = {}
            for k, v in obj.items():
                if v is not None:
                    new_dict[k] = remove_none(v)
            return new_dict
        elif isinstance(obj, list):
            new_list = [remove_none(item) for item in obj if item is not None]
            return new_list
        else:
            return obj

    data_clean = remove_none(data)

    def flatten_values(obj):
        if isinstance(obj, (str, int, float, bool)):
            yield obj
        elif isinstance(obj, dict):
            for v in obj.values():
                yield from flatten_values(v)
        elif isinstance(obj, list):
            for item in obj:
                yield from flatten_values(item)

    value_counter = Counter(flatten_values(data_clean))

    EMAIL_PATTERN = r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'

    def replace_emails(obj):
        if isinstance(obj, str):
            return re.sub(EMAIL_PATTERN, REPLACE_NONE, obj)
        elif isinstance(obj, dict):
            return {k: replace_emails(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [replace_emails(item) for item in obj]
        else:
            return obj

    data_final = replace_emails(data_clean)

    return {"data": data_final, "value_counts": value_counter}

