import seaborn as sns
import pandas as pd
def task_func(json_data: str, key_path: list):
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError:
        raise ValueError("Corrupted JSON data")

    for key in key_path:
        if isinstance(data, dict) and key in data:
            data = data[key]
        else:
            raise KeyError(f"Key '{key}' not found")

    if isinstance(data, (int, float)):
        values = [data]
    elif isinstance(data, list):
        if not data:
            raise ValueError("No numeric data found (empty list)")
        values = []
        for item in data:
            if isinstance(item, (int, float)):
                values.append(item)
            else:
                raise ValueError("Non-numeric value found in data")
    else:
        raise ValueError("Data is not numeric or list of numerics")

    fig, ax = plt.subplots()
    sns.boxplot(data=values, ax=ax)
    return fig
